{"code":"def transform(grid):
    h=len(grid); w=len(grid[0]); bg=grid[0][0]
    vals={x for r in grid for x in r if x!=bg}
    line=next(iter(vals),bg)
    fr=[i for i,r in enumerate(grid) if all(x==line for x in r)]
    fc=[j for j in range(w) if all(grid[i][j]==line for i in range(h))]
    if not fc:
        nr=len({tuple(r) for r in grid}); nc=1
    else:
        nr=len(fr)+1; nc=len(fc)+1
    return [[bg]*nc for _ in range(nr)]"}

